// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    Recorder rec;

    function setUp() public {
        c = new SimpleWallet();
        rec = new Recorder();
        vm.deal(address(this), type(uint256).max / 2);
        (bool s, ) = address(c).call{value: 10 ether}("");
        require(s, "fund c failed");
    }

    function testFuzz_property(uint256 amount) public {
        uint256 value = bound(amount, 1 wei, 5 ether);
        vm.prank(c.owner());
        c.sendMoney(address(rec), value);
        assertTrue(rec.totalReceived() == value && rec.calls() == 1);
    }
}

contract Recorder {
    uint256 public totalReceived;
    uint256 public calls;
    receive() external payable {
        totalReceived += msg.value;
        calls++;
    }
}
